er_factory=factory, stop_event=stopped, started=started) except BaseException as error: caught = error try: reports.put({name: resource._db.execute('SELECT 1').fetchone()[0] if resource._db is not None else None for name, resource in acquired.items()}) finished.put(caught) assert release.wait(timeout=5) finally: # Owner-thread disposal happens only after parent observes the result. real_close['domain'](); real_close['store']() thread = threading.Thread(target=run, daemon=True); thread.start() try: caught = finished.get(timeout=5); state = reports.get(timeout=1); address = bound.get(timeout=1) graph = errors(caught) assert any(error is primary for error in graph) and primary.__traceback__ is not None > assert attempted == ['domain', 'store'] E AssertionError: assert [] == ['domain', 'store'] E E Right contains 2 more items, first extra item: 'domain' E Use -v to get more diff
